//
  document.documentElement.className += ' js';
  /* Cosmetic: hide Blogger's ?m=1 from the address bar (the page is identical either way) */
  try {
    var u = new URL(location.href);
    if (u.searchParams.get('m') === '1' && history.replaceState) {
      u.searchParams.delete('m');
      history.replaceState(null, '', u.toString());
    }
  } catch (e) {}
  //

