head.b:skin:
/* ==========================================================================
   0. DESIGN TOKENS
   ========================================================================== */
:root{
  --cream:#FAF6EC; --cream-2:#F2EAD8; --white:#fff;
  --ink:#1C1810; --ink-soft:rgba(28,24,16,.72); --ink-faint:rgba(28,24,16,.5);
  --forest:#1E3626; --forest-2:#142519; --forest-tint:#2C4736;
  --mango:#E39A2E; --mango-deep:#A85F14; --mango-pale:#F3C876;
  --line:rgba(28,24,16,.12); --line-dark:rgba(250,246,236,.16);
  --display:"Fraunces",Georgia,"Times New Roman",serif;
  --body:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;
  --wrap:1200px; --narrow:760px;
  --gutter:clamp(1rem,4vw,3rem);
  --pad:clamp(3.5rem,8vw,7rem);
  --r:12px; --ease:cubic-bezier(.22,.61,.36,1);
}

/* ==========================================================================
   1. BASE
   ========================================================================== */
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--cream);color:var(--ink);font:16px/1.65 var(--body);-webkit-font-smoothing:antialiased;overflow-x:hidden}
img,svg,video,iframe{max-width:100%;display:block}
img{height:auto}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--display);font-weight:500;line-height:1.12;letter-spacing:-.01em;margin:0 0 .5em}
p{margin:0 0 1em}
ul,ol{margin:0;padding:0}
button,input,select,textarea{font:inherit}
:focus-visible{outline:2px solid var(--mango);outline-offset:3px}
.skip-link{position:absolute;left:-999px;top:0;z-index:1000;background:var(--forest);color:var(--cream);padding:.8em 1.2em}
.skip-link:focus{left:0}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}

/* Placeholder photo slots: until a real URL is pasted, show the branded gradient */
.media{display:block;position:relative;overflow:hidden;border-radius:var(--r);background:radial-gradient(circle at 25% 20%,rgba(227,154,46,.4),transparent 55%),linear-gradient(135deg,#23402C,#1A2E20)}
.media img{width:100%;height:100%;object-fit:cover}
img[src^="data:,"]{opacity:0}

.wrap{max-width:var(--wrap);margin-inline:auto;padding-inline:var(--gutter)}
.wrap--narrow{max-width:var(--narrow)}
.section{padding-block:var(--pad)}
.section--tint{background:var(--cream-2)}
.section--dark{background:var(--forest-2);color:var(--cream)}
.section--forest{background:var(--forest);color:var(--cream)}

.eyebrow{display:inline-block;font-size:.75rem;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--mango-deep);margin-bottom:1em}
.section--dark .eyebrow,.section--forest .eyebrow{color:var(--mango-pale)}
.title{font-size:clamp(1.9rem,4.2vw,3.2rem);max-width:20ch}
.lede{font-size:clamp(1.02rem,1.5vw,1.2rem);color:var(--ink-soft);max-width:56ch}
.section--dark .lede,.section--forest .lede{color:rgba(250,246,236,.78)}
.head{margin-bottom:clamp(2rem,5vw,3.5rem)}
.head--split{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:flex-end;gap:1.5rem}
.center{text-align:center}
.center .title,.center .lede{margin-inline:auto}

/* ==========================================================================
   2. BUTTONS (min 48px tap height)
   ========================================================================== */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.55em;min-height:48px;padding:.8em 1.6em;border-radius:999px;border:1px solid transparent;font-size:.95rem;font-weight:600;line-height:1.2;cursor:pointer;transition:transform .25s var(--ease),background .25s var(--ease),color .25s var(--ease)}
.btn:hover{transform:translateY(-2px)}
.btn svg{width:20px;height:20px;flex:none}
.btn--primary{background:var(--mango);color:var(--forest-2)}
.btn--primary:hover{background:var(--mango-deep);color:var(--white)}
.btn--outline{border-color:currentColor;background:transparent;color:inherit}
.btn--outline:hover{background:var(--ink);color:var(--cream);border-color:var(--ink)}
.section--dark .btn--outline:hover,.section--forest .btn--outline:hover,.hero .btn--outline:hover,.cta .btn--outline:hover{background:var(--cream);color:var(--forest-2);border-color:var(--cream)}
.btn--wa{background:var(--forest);color:var(--cream)}
.btn--wa:hover{background:var(--forest-2)}
.section--dark .btn--wa,.section--forest .btn--wa{background:var(--mango);color:var(--forest-2)}
.btn--sm{min-height:42px;padding:.6em 1.2em;font-size:.85rem}
.btn-row{display:flex;flex-wrap:wrap;gap:.8rem}
.link-arrow{font-weight:600;color:var(--mango-deep);border-bottom:1px solid currentColor;padding-bottom:2px}
.section--dark .link-arrow,.section--forest .link-arrow{color:var(--mango-pale)}

/* ==========================================================================
   3. HEADER & NAV
   ========================================================================== */
.site-header{position:fixed;top:0;left:0;right:0;z-index:500;padding-block:1rem;transition:background .3s var(--ease),padding .3s var(--ease),box-shadow .3s var(--ease);background:linear-gradient(to bottom,rgba(20,37,25,.6),rgba(20,37,25,0))}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem}
.brand{font-family:var(--display);font-size:1.05rem;font-weight:600;letter-spacing:.05em;text-transform:uppercase;color:var(--cream);display:flex;align-items:center;gap:.55rem;min-height:44px}
.brand svg{width:26px;height:26px;flex:none}
.nav{display:none}
.nav ul{display:flex;gap:1.75rem;list-style:none}
.nav a{font-size:.9rem;font-weight:500;color:var(--cream);padding-block:.5em;position:relative}
.nav a::after{content:"";position:absolute;left:0;bottom:.2em;width:0;height:1px;background:currentColor;transition:width .3s var(--ease)}
.nav a:hover::after{width:100%}
.header-cta{display:none}
.menu-btn{display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;border-radius:50%;border:1px solid var(--line-dark);background:transparent;color:var(--cream);cursor:pointer}
.menu-btn svg{width:22px;height:22px}
.menu-btn .i-close{display:none}
.menu-open .menu-btn .i-open{display:none}
.menu-open .menu-btn .i-close{display:block}

/* Solid header: after scrolling, and always on inner pages */
.site-header.is-solid,.is-inner .site-header{background:rgba(250,246,236,.96);box-shadow:0 1px 0 var(--line);padding-block:.6rem;-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}
.site-header.is-solid .brand,.is-inner .site-header .brand,
.site-header.is-solid .nav a,.is-inner .site-header .nav a,
.site-header.is-solid .menu-btn,.is-inner .site-header .menu-btn{color:var(--ink)}
.site-header.is-solid .menu-btn,.is-inner .site-header .menu-btn{border-color:var(--line)}
.menu-open .site-header .brand,.menu-open .site-header .menu-btn{color:var(--cream)}
.menu-open .site-header{background:transparent;box-shadow:none}

.mobile-nav{position:fixed;inset:0;z-index:490;background:var(--forest-2);color:var(--cream);padding:6rem var(--gutter) 2rem;display:flex;flex-direction:column;gap:2rem;overflow-y:auto;transform:translateY(-100%);visibility:hidden;transition:transform .45s var(--ease),visibility 0s .45s}
.menu-open .mobile-nav{transform:none;visibility:visible;transition:transform .45s var(--ease)}
.menu-open{overflow:hidden}
.mobile-nav ul{list-style:none;display:flex;flex-direction:column}
.mobile-nav ul a{display:block;font-family:var(--display);font-size:1.6rem;padding:.45em 0;border-bottom:1px solid var(--line-dark)}
.mobile-nav .btn-row{flex-direction:column}
.mobile-nav .btn{width:100%}

@media (min-width:960px){
  .nav{display:block}
  .header-cta{display:inline-flex}
  .menu-btn,.mobile-nav{display:none}
}

/* ==========================================================================
   4. HOMEPAGE
   ========================================================================== */
.hero{position:relative;min-height:92vh;min-height:92svh;display:flex;align-items:flex-end;color:var(--cream);background:var(--forest-2);overflow:hidden}
.hero .media{position:absolute;inset:0;border-radius:0}
.hero .media::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(18,36,26,.45) 0%,rgba(18,36,26,.15) 40%,rgba(18,36,26,.9) 100%)}
.hero-content{position:relative;z-index:2;width:100%;padding-block:8rem clamp(3rem,8vw,6rem)}
.hero h1{font-size:clamp(2.3rem,6.4vw,4.8rem);max-width:17ch;color:var(--white)}
.hero .lede{color:rgba(250,246,236,.86);max-width:46ch;margin-bottom:2rem}
.hero .eyebrow{color:var(--mango-pale)}

.trust{background:var(--forest);color:var(--cream);padding-block:1.6rem}
.trust ul{list-style:none;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem 1.5rem}
.trust li{display:flex;align-items:center;gap:.7rem;font-size:.9rem;font-weight:500}
.trust svg{width:22px;height:22px;flex:none;color:var(--mango-pale)}
@media (min-width:860px){.trust ul{grid-template-columns:repeat(4,minmax(0,1fr))}}

.cards{display:grid;gap:1.25rem;grid-template-columns:repeat(auto-fill,minmax(min(100%,250px),1fr))}
.card{background:var(--white);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;display:flex;flex-direction:column;transition:transform .3s var(--ease),box-shadow .3s var(--ease)}
.card:hover{transform:translateY(-4px);box-shadow:0 14px 30px rgba(20,37,25,.1)}
.card .media{aspect-ratio:4/3;border-radius:0}
.card-body{padding:1.25rem 1.3rem 1.4rem;display:flex;flex-direction:column;gap:.35rem;flex-grow:1}
.card-body h3{font-size:1.35rem;margin:0}
.card-body p{font-size:.93rem;color:var(--ink-soft);margin:0}
.card-tag{font-size:.7rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--mango-deep)}
.card-body .link-arrow{margin-top:auto;padding-top:.6rem;align-self:flex-start;border:0}

.split{display:grid;gap:clamp(2rem,5vw,4.5rem);grid-template-columns:minmax(0,1fr);align-items:center}
.split .media{aspect-ratio:4/5}
@media (min-width:900px){.split{grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr)}.split--rev .split-media{order:-1}}
.split p{color:var(--ink-soft);font-size:1.03rem}
.section--dark .split p,.section--forest .split p{color:rgba(250,246,236,.78)}

.steps{list-style:none;display:grid;gap:1px;background:var(--line-dark);grid-template-columns:minmax(0,1fr);border-radius:var(--r);overflow:hidden;counter-reset:s}
.steps li{background:var(--forest);padding:2rem 1.75rem;counter-increment:s}
.steps li::before{content:"0" counter(s);display:block;font-family:var(--display);font-size:2.2rem;color:rgba(250,246,236,.3);margin-bottom:.6rem}
.steps h3{font-size:1.15rem;margin-bottom:.4rem}
.steps p{font-size:.93rem;color:rgba(250,246,236,.75);margin:0}
@media (min-width:760px){.steps{grid-template-columns:repeat(3,minmax(0,1fr))}}

.tags{display:flex;flex-wrap:wrap;gap:.5rem;margin-block:1.25rem 1.75rem;list-style:none}
.tags li,.tags a{font-size:.8rem;padding:.45em 1em;border:1px solid var(--line);border-radius:999px;color:var(--ink-soft)}
.section--dark .tags li,.section--forest .tags li{border-color:var(--line-dark);color:rgba(250,246,236,.8)}

.duo{display:grid;gap:1.25rem;grid-template-columns:minmax(0,1fr)}
@media (min-width:820px){.duo{grid-template-columns:repeat(2,minmax(0,1fr))}}
.panel{border:1px solid var(--line-dark);border-radius:var(--r);padding:clamp(1.5rem,4vw,2.5rem);background:rgba(250,246,236,.04)}
.panel h3{font-size:1.5rem}
.panel p{color:rgba(250,246,236,.78)}

.cta{position:relative;color:var(--white);text-align:center;overflow:hidden;background:var(--forest-2)}
.cta .media{position:absolute;inset:0;border-radius:0}
.cta .media::after{content:"";position:absolute;inset:0;background:rgba(18,30,20,.68)}
.cta-content{position:relative;z-index:1;padding-block:clamp(4.5rem,10vw,8rem)}
.cta h2{font-size:clamp(2rem,5vw,3.4rem);color:var(--white)}
.cta .lede{color:rgba(255,255,255,.86);margin-inline:auto}
.cta .btn-row{justify-content:center;margin-top:1.75rem}

/* ==========================================================================
   5. POSTS, PAGES & LISTINGS (Blog1 widget)
   ========================================================================== */
.page-hero{background:var(--forest-2);color:var(--cream);padding:clamp(7.5rem,14vw,10rem) 0 clamp(2.5rem,5vw,3.5rem)}
.page-hero h1{font-size:clamp(2rem,5vw,3.4rem);max-width:24ch;color:var(--white);margin:0}
.page-hero .eyebrow{color:var(--mango-pale)}
.crumbs{font-size:.82rem;color:rgba(250,246,236,.65);margin-bottom:1rem}
.crumbs a{text-decoration:underline;text-underline-offset:2px}
.post-meta{display:flex;flex-wrap:wrap;gap:.4em .9em;margin-top:1rem;font-size:.88rem;color:rgba(250,246,236,.7)}

.entry{padding-block:clamp(2.5rem,6vw,4.5rem) var(--pad)}
.entry-content{font-size:1.06rem;max-width:var(--narrow);margin-inline:auto}
.entry-content > *{max-width:100%}
.entry-content > .band{max-width:none}
.entry-content h2{font-size:clamp(1.5rem,3vw,2.1rem);margin-top:2.2em}
.entry-content h3{font-size:1.3rem;margin-top:1.8em}
.entry-content a{color:var(--mango-deep);text-decoration:underline;text-underline-offset:2px}
.entry-content a.btn{text-decoration:none}
.entry-content a.btn--primary{color:var(--forest-2)}
.entry-content a.btn--wa{color:var(--cream)}
.entry-content ul,.entry-content ol{padding-left:1.3em;margin:0 0 1.2em}
.entry-content li{margin-bottom:.4em}
.entry-content img{border-radius:var(--r);margin-block:1.25em;height:auto!important}
.entry-content .separator a{margin:0!important}
.entry-content blockquote{margin:1.5em 0;padding:1em 1.4em;border-left:3px solid var(--mango);background:var(--cream-2);border-radius:0 var(--r) var(--r) 0}
.entry-content table{width:100%;border-collapse:collapse;margin:1.5em 0;font-size:.95rem;display:block;overflow-x:auto}
.entry-content th,.entry-content td{text-align:left;padding:.75em .9em;border-bottom:1px solid var(--line);vertical-align:top}
.entry-content th{font-size:.75rem;letter-spacing:.06em;text-transform:uppercase;color:var(--mango-deep);background:var(--cream-2)}
.entry-content iframe{width:100%;border:0;border-radius:var(--r)}

/* Full-width bands inside page content: <div class="band"> ... </div> */
.entry-content .band{width:100vw;margin-left:calc(50% - 50vw);padding:clamp(2.5rem,6vw,4.5rem) var(--gutter);background:var(--cream-2);margin-block:2.5em}
.entry-content .band > *{max-width:var(--narrow);margin-inline:auto}
.entry-content .band--dark{background:var(--forest-2);color:var(--cream)}
.entry-content .band--dark a:not(.btn){color:var(--mango-pale)}
.entry-content .band--dark h2,.entry-content .band--dark h3{color:var(--white)}

/* Reusable content blocks for pages */
.entry-content .grid{display:grid;gap:1.25rem;grid-template-columns:repeat(auto-fill,minmax(min(100%,220px),1fr));margin:1.5em 0}
.entry-content .box{background:var(--white);border:1px solid var(--line);border-radius:var(--r);padding:1.4rem}
.entry-content .box h3{margin-top:0;font-size:1.15rem}
.entry-content .box p:last-child{margin:0}
.entry-content .band--dark .box{background:rgba(250,246,236,.05);border-color:var(--line-dark)}
.entry-content .variety{display:grid;gap:1.5rem;grid-template-columns:minmax(0,1fr);align-items:start;padding-block:1.5em;border-top:1px solid var(--line)}
.entry-content .variety h2{margin-top:0}
.entry-content .variety img{margin:0;aspect-ratio:4/3;object-fit:cover;width:100%}
@media (min-width:720px){.entry-content .variety{grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr)}}
.entry-content .tags{padding-left:0}
.entry-content .facts{list-style:none;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.6rem 1rem;font-size:.92rem}
.entry-content .facts li{margin:0}
.entry-content .facts strong{display:block;font-size:.7rem;letter-spacing:.08em;text-transform:uppercase;color:var(--mango-deep)}
.entry-content details{border-bottom:1px solid var(--line);padding:1em 0}
.entry-content summary{cursor:pointer;font-weight:600;font-size:1.05rem;list-style-position:inside;min-height:44px;display:list-item}
.entry-content details p{margin:.75em 0 0;color:var(--ink-soft)}
.entry-content .note{font-size:.88rem;color:var(--ink-faint)}

/* Listing cards (blog index, labels, search, homepage journal) */
.post-grid{display:grid;gap:2rem 1.5rem;grid-template-columns:repeat(auto-fill,minmax(min(100%,290px),1fr))}
.post-card .media{aspect-ratio:4/3;display:block;margin-bottom:1rem}
.post-card time{font-size:.75rem;letter-spacing:.08em;text-transform:uppercase;color:var(--mango-deep)}
.post-card h2,.post-card h3{font-size:1.3rem;margin:.3rem 0 .5rem}
.post-card h2 a:hover,.post-card h3 a:hover{text-decoration:underline}
.post-card p{color:var(--ink-soft);font-size:.95rem}
.pager{display:flex;justify-content:space-between;gap:1rem;margin-top:3rem}
.post-labels{max-width:var(--narrow);margin:2.5rem auto 0;display:flex;flex-wrap:wrap;gap:.5rem;list-style:none}
.post-labels a{font-size:.8rem;padding:.45em 1em;border:1px solid var(--line);border-radius:999px;color:var(--ink-soft);text-decoration:none}
.post-share{max-width:var(--narrow);margin:2rem auto 0;padding-top:2rem;border-top:1px solid var(--line);display:flex;flex-wrap:wrap;gap:.8rem;align-items:center}
.empty{padding-block:2rem;color:var(--ink-soft)}

/* ==========================================================================
   6. FORMS (WhatsApp order / inquiry forms)
   ========================================================================== */
.form{background:var(--white);border:1px solid var(--line);border-radius:var(--r);padding:clamp(1.25rem,4vw,2.25rem);margin:1.5em 0}
.form h3{margin-top:0}
.form-row{display:grid;gap:1rem;grid-template-columns:minmax(0,1fr);margin-bottom:1rem}
@media (min-width:620px){.form-row--2{grid-template-columns:repeat(2,minmax(0,1fr))}}
.field{display:flex;flex-direction:column;gap:.4rem}
.field label{font-size:.82rem;font-weight:600}
.field input,.field select,.field textarea{width:100%;min-height:48px;border:1px solid var(--line);background:var(--cream);border-radius:8px;padding:.7em .85em;color:var(--ink);font-size:16px}
.field textarea{min-height:110px;resize:vertical}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--mango);outline:none}
.form-note{font-size:.82rem;color:var(--ink-faint);margin:.8rem 0 0}
.band--dark .form,.section--dark .form{background:rgba(250,246,236,.05);border-color:var(--line-dark)}
.band--dark .field input,.band--dark .field select,.band--dark .field textarea{background:rgba(250,246,236,.07);border-color:var(--line-dark);color:var(--cream)}
.band--dark .field select option{color:var(--ink)}
.band--dark .form-note,.section--dark .form-note{color:rgba(250,246,236,.6)}
.band--dark .form h3{color:var(--white)}

/* ==========================================================================
   7. FOOTER & FLOATING WHATSAPP
   ========================================================================== */
.site-footer{background:var(--forest-2);color:rgba(250,246,236,.76);padding-block:3.5rem 6rem;font-size:.93rem}
.footer-grid{display:grid;gap:2rem;grid-template-columns:minmax(0,1fr);margin-bottom:2.5rem}
@media (min-width:760px){.footer-grid{grid-template-columns:minmax(0,1.4fr) minmax(0,1fr) minmax(0,1fr)}}
.site-footer .f-brand{font-family:var(--display);color:var(--white);font-size:1.35rem;margin-bottom:.5rem}
.site-footer h2{font-family:var(--body);font-size:.74rem;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:rgba(250,246,236,.5);margin-bottom:.9rem}
.site-footer ul{list-style:none;display:flex;flex-direction:column;gap:.2rem}
.site-footer ul a{display:inline-block;padding-block:.35em}
.site-footer a:hover{text-decoration:underline}
.footer-bottom{border-top:1px solid var(--line-dark);padding-top:1.4rem;display:flex;flex-wrap:wrap;justify-content:space-between;gap:.75rem;font-size:.8rem;color:rgba(250,246,236,.5)}

.wa-float{position:fixed;right:1rem;bottom:1rem;z-index:400;width:58px;height:58px;border-radius:50%;background:#25D366;color:#fff;display:flex;align-items:center;justify-content:center;box-shadow:0 8px 24px rgba(18,30,20,.35);transition:transform .25s var(--ease)}
.wa-float:hover{transform:scale(1.07)}
.wa-float svg{width:30px;height:30px}

/* 404 */
.not-found{padding:clamp(8rem,16vw,12rem) 0 6rem;text-align:center}
.not-found .btn-row{justify-content:center}

/* ==========================================================================
   8. MOTION (only when JS is running; respects reduced motion)
   ========================================================================== */
.js .reveal{opacity:0;transform:translateY(28px);transition:opacity .9s var(--ease),transform .9s var(--ease)}
.js .reveal.is-in{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{transition:none!important;animation:none!important}
  .js .reveal{opacity:1;transform:none}
}

/* Hide Blogger's own chrome that may be injected */
#Navbar1,.navbar,#b-navbar,.blogger-clickTrap{display:none!important}
.widget{margin:0}
/* Blogger adds class="section" to its section wrapper; cancel the theme's .section padding there */
#blog-main.section{padding:0;margin:0}

body.script:
//
(function () {
  'use strict';
  var WA_NUMBER = '923144419652'; /* [CONTACT] WhatsApp number used by all forms */
  var doc = document.documentElement;
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* Header turns solid after scrolling */
  var header = document.getElementById('site-header');
  function onScroll() { header.classList.toggle('is-solid', window.scrollY > 40); }
  onScroll();
  window.addEventListener('scroll', onScroll, { passive: true });

  /* Mobile menu */
  var btn = document.getElementById('menu-btn');
  var mnav = document.getElementById('mobile-nav');
  function setMenu(open) {
    doc.classList.toggle('menu-open', open);
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    btn.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
  }
  btn.addEventListener('click', function () { setMenu(!doc.classList.contains('menu-open')); });
  mnav.addEventListener('click', function (e) { if (e.target.closest('a')) setMenu(false); });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') setMenu(false); });

  /* Scroll reveal */
  var els = document.querySelectorAll('.reveal');
  if (reduce || !('IntersectionObserver' in window)) {
    els.forEach(function (el) { el.classList.add('is-in'); });
  } else {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) { en.target.classList.add('is-in'); io.unobserve(en.target); }
      });
    }, { threshold: 0.12, rootMargin: '0px 0px -6% 0px' });
    els.forEach(function (el) { io.observe(el); });
  }

  /* WhatsApp forms: any <form data-wa-form="Title"> sends its fields as a WhatsApp message */
  document.querySelectorAll('form[data-wa-form]').forEach(function (form) {
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      if (!form.checkValidity()) { form.reportValidity(); return; }
      var lines = ['*' + form.getAttribute('data-wa-form') + '* — Ghulam Hussain Farms', ''];
      form.querySelectorAll('input, select, textarea').forEach(function (f) {
        if (!f.name || !f.value.trim()) return;
        var label = form.querySelector('label[for="' + f.id + '"]');
        lines.push((label ? label.textContent.replace('*', '').trim() : f.name) + ': ' + f.value.trim());
      });
      window.open('https://wa.me/' + WA_NUMBER + '?text=' + encodeURIComponent(lines.join('\n')), '_blank', 'noopener');
    });
  });

  var y = document.getElementById('year');
  if (y) y.textContent = new Date().getFullYear();
})();
//
